import json
# check duplicate key detection timing and object_pairs_hook raising
def hook(pairs):
    d={}
    for k,v in pairs:
        if k in d: raise ValueError('dup')
        d[k]=v
    return d
try:
    json.loads('{\"a\":1,\"a\":2}', object_pairs_hook=hook)
except Exception as e: print('dup caught', e)
